const num = (v: unknown): number | null => {
  const n = typeof v === 'number' ? v : typeof v === 'string' ? Number(v) : NaN
  return Number.isFinite(n) ? n : null
}
const ageMs = (iso: string | null | undefined): number => {
  const t = Date.parse(iso ?? '')
  return Number.isFinite(t) ? Date.now() - t : 0
}
const nowIso = () => new Date().toISOString()
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms))

// ── linhas iniciais ───────────────────────────────────────────────────────────────────────────────────────────────
/**
 * As linhas de plano (tentativa 1) de uma geração paga. REGRA DURA: plano `text` nasce 'skipped_text', sem motor,
 * sem prompt de vídeo e com a própria foto como stored_url — nunca vai à fal (o CHECK ads_v2_shots_text_never_ai
 * repete a regra no banco).
 */
export function buildInitialShotRows(orderId: string, tier: AdsV2Tier, plan: Pick<AdsV2ShotPlan, 'shots'> & { presenter?: unknown }): Record<string, unknown>[] {
  const rows = plan.shots.map((s): Record<string, unknown> => {
    // KINEO-ADS-VIDEO-DO-CLIENTE-2026-09-29 — o vídeo do cliente nasce 'done': sem motor, sem prompt, sem imagem, com o
    // próprio arquivo como stored_url e a duração MEDIDA pelo servidor. Nunca vai à fal (o CHECK
    // ads_v2_shots_user_video_never_ai, migrations_pending/2026-09-29_ads_v2_user_video.sql, repete a regra no banco).
    if (s.kind === 'user_video') {
      return {
        order_id: orderId,
        idx: s.idx,
        attempt: 1,
        role: s.role,
        kind: 'user_video',
        source: 'client_photo',
        source_footage_id: s.sourceFootageId,
        image_url: null,
        engine: null,
        prompt: null,
        gen_seconds: null,
        cut_start: s.cutStart,
        cut_seconds: s.cutSeconds,
        movement_variant: 0,
        status: 'done',
        stored_url: s.videoUrl ?? null,
        measured_seconds: s.videoSeconds ?? null,
        usd: 0,
      }
    }
    const isText = s.kind === 'text'
    // KINEO-ESTILOS-PRODUTO-2026-10-09 — plano-herói com estilo nasce no efeito da PixVerse (sem estilo: a rota de antes).
    const engine = isText ? null : routeShot(s.kind, tier, 1, isAdsV2PlanStyle(s.effect))
    return {
      order_id: orderId,
      idx: s.idx,
      attempt: 1,
      role: s.role,
      kind: s.kind,
      source: s.source,
      source_footage_id: s.sourceFootageId,
      image_url: s.source === 'client_photo' ? s.imageUrl : null,
      engine,
      prompt: isText ? null : s.prompt,
      gen_seconds: engine ? ADS_V2_ENGINES[engine].genSeconds : null,
      cut_start: s.cutStart,
      cut_seconds: s.cutSeconds,
      movement_variant: s.movementVariant,
      status: isText ? 'skipped_text' : 'pending',
      stored_url: isText ? s.imageUrl : null,
    }
  })
  // KINEO-ATOR-ANUNCIO-2026-10-09 — com ator no plano, + UMA linha (a dele) depois dos planos; sem ator, as linhas de antes.
  return isAdsV2PresenterPlan(plan.presenter) ? [...rows, adsV2PresenterInitialRow(orderId, plan.presenter)] : rows
}

/** KINEO-ATOR-ANUNCIO-2026-10-09 — a linha é a do ator (fora da lista de planos do anúncio)? */
export function isAdsV2PresenterRow(r: Pick<AdsV2ShotRow, 'kind'>): boolean {
  return r.kind === ADS_V2_PRESENTER_KIND
}
/** KINEO-ATOR-ANUNCIO-2026-10-09 — a linha é um PLANO do anúncio (tudo menos o ator). */
export function isAdsV2PlanShotRow(r: AdsV2ShotRow): r is AdsV2ShotRow & { kind: AdsV2ShotKind } {
  return r.kind !== ADS_V2_PRESENTER_KIND
}
/** KINEO-ATOR-ANUNCIO-2026-10-09 — o ator gravado no plano do pedido (null = pedido sem ator). */
export function adsV2PresenterPlanOf(plan: { presenter?: unknown } | null | undefined): AdsV2PresenterPlan | null {
  return plan && isAdsV2PresenterPlan(plan.presenter) ? plan.presenter : null
}
/** KINEO-ATOR-ANUNCIO-2026-10-09 — a voz do pedido está pronta e cabe no ator (só então o vídeo falado sai). */
export function adsV2PresenterVoiceReady(order: Pick<AdsV2OrderRow, 'narration' | 'voice_url' | 'voice_seconds' | 'seconds'>): boolean {
  return order.narration === true && typeof order.voice_url === 'string' && /^https:\/\//i.test(order.voice_url) && adsV2PresenterVoiceFits(num(order.voice_seconds), order.seconds)
}

export async function loadAdsV2Order(admin: SupabaseClient, orderId: string, userId?: string): Promise<{ order: AdsV2OrderRow | null; error: { code?: string; message?: string } | null }> {
  let q = admin.from('ads_v2_orders').select(ADS_V2_ORDER_COLS).eq('id', orderId)
  if (userId) q = q.eq('user_id', userId)
  const { data, error } = await q.maybeSingle()
  return { order: (data as AdsV2OrderRow | null) ?? null, error: error ? { code: error.code, message: error.message } : null }
}

export async function loadAdsV2Shots(admin: SupabaseClient, orderId: string): Promise<AdsV2ShotRow[] | null> {
  const { data, error } = await admin.from('ads_v2_shots').select(ADS_V2_SHOT_COLS).eq('order_id', orderId).order('idx', { ascending: true }).order('attempt', { ascending: true })
  if (error) return null
  return (data ?? []) as AdsV2ShotRow[]
}

/** A tentativa mais nova de cada plano. */
export function latestShots(rows: readonly AdsV2ShotRow[]): AdsV2ShotRow[] {
  const by = new Map<number, AdsV2ShotRow>()
  for (const r of rows) {
    const cur = by.get(r.idx)
    if (!cur || r.attempt > cur.attempt) by.set(r.idx, r)
  }
  return [...by.values()].sort((a, b) => a.idx - b.idx)
}

const READY = new Set(['done', 'skipped_text'])

/**
 * KINEO-ESTILOS-PRODUTO-2026-10-09 — a chave do estilo do plano `idx` gravada no plano do pedido (planShots marca o
 * `effect` só no plano-herói do produto). null = plano sem estilo (rota e entrada de antes). Refação e variações copiam o
 * plano do pai, então o estilo vai junto.
 */
export function adsV2ShotEffect(plan: Pick<AdsV2ShotPlan, 'shots'> | null | undefined, idx: number): string | null {
  const s = Array.isArray(plan?.shots) ? plan!.shots.find((x) => x.idx === idx) : undefined
  return s && isAdsV2PlanStyle(s.effect) ? s.effect : null
}

// ── KINEO-ADS-FIEL-1510 — trava do produto e prazo por plano (as decisões puras moram em lib/ads/v2ShotLists.ts) ──────────────
/** KINEO-ADS-FIEL-1510 — a trava deste plano (null = plano sem produto: o caminho de antes). brief.kind 'place' nunca trava. */
export function adsV2LockOf(order: Pick<AdsV2OrderRow, 'brief' | 'plan' | 'photos' | 'sector'>, row: Pick<AdsV2ShotRow, 'idx' | 'kind'>): AdsV2ProductLock | null {
  const kind = order.brief && typeof order.brief.kind === 'string' ? order.brief.kind : null
  const isActor = row.kind === ADS_V2_PRESENTER_KIND
  const actor = isActor ? adsV2PresenterPlanOf(order.plan) : null
  if (isActor && !actor) return null
  const shot = Array.isArray(order.plan?.shots) ? order.plan!.shots.find((s) => s.idx === row.idx) ?? null : null
  if (!isActor && shot && (shot as { inHand?: unknown }).inHand) return null // KINEO-ADS-PRODUTO-NA-MAO-1610 — o plano novo NUNCA passa pela colagem (o modelo vê a foto real e põe o produto na mão)
  return adsV2ProductLockFor({ shot: isActor ? null : shot, photos: order.photos, productOrder: kind === 'product', sector: kind === 'place' ? null : order.sector, actor })
}
/** KINEO-ADS-FIEL-1510 — o lado servidor da trava, carregado só quando há produto a travar (import dinâmico; falha = sem trava). */
function lockServer() {
  return import('@/lib/ads/v2ProductLockServer').catch(() => null)
}
/** KINEO-ADS-FIEL-2-1510 — a conferência de produto na cena (modelo de visão do registro central), import dinâmico; falha = sem conferência. */
function lockVision() { // KINEO-ADS-FIEL-2-1510
  return import('@/lib/ads/v2LockVision').catch(() => null) // KINEO-ADS-FIEL-2-1510
} // KINEO-ADS-FIEL-2-1510
/**
 * KINEO-ADS-FIEL-2-1510 — o CLOSE do Premium com a trava: a vaga vira a FOTO REAL do produto com o zoom de close do montador (o caminho do
 * plano `text`: sem motor, sem fal, sem cobrança, fora do teto de fotos paradas). Só um vence (upsert sem duplicar).
 */
async function closeupStill(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow): Promise<boolean> { // KINEO-ADS-FIEL-2-1510
  const url = (row.image_url ?? '').trim() // KINEO-ADS-FIEL-2-1510
  const next = { // KINEO-ADS-FIEL-2-1510
    order_id: order.id, idx: row.idx, attempt: row.attempt + 1, role: row.role, kind: 'text', source: row.source, source_footage_id: row.source_footage_id, // KINEO-ADS-FIEL-2-1510
    image_url: url, engine: null, prompt: null, gen_seconds: null, cut_start: 0, cut_seconds: row.cut_seconds, movement_variant: row.movement_variant, // KINEO-ADS-FIEL-2-1510
    status: 'skipped_text', stored_url: url, reason: ADS_V2_LOCK_CLOSEUP_REASON, // KINEO-ADS-FIEL-2-1510
  } // KINEO-ADS-FIEL-2-1510
  const ins = await admin.from('ads_v2_shots').upsert(next, { onConflict: 'order_id,idx,attempt', ignoreDuplicates: true }).select('id') // KINEO-ADS-FIEL-2-1510
  const won = !ins.error && Array.isArray(ins.data) && ins.data.length > 0 // KINEO-ADS-FIEL-2-1510
  if (won) await shotFallbackEvent(order, row, { to: 'real_closeup', reason: ADS_V2_LOCK_CLOSEUP_REASON, next_attempt: next.attempt }) // KINEO-ADS-FIEL-2-1510
  return won // KINEO-ADS-FIEL-2-1510
} // KINEO-ADS-FIEL-2-1510
/** KINEO-ADS-FIEL-1510 — evento de toda troca de caminho de um plano (motor de reserva, foto parada, foto real do produto). */
function shotFallbackEvent(order: AdsV2OrderRow, row: AdsV2ShotRow, metadata: Record<string, unknown>): Promise<unknown> {
  return writeServerEvent({ name: 'ads_v2_shot_fallback', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, idx: row.idx, attempt: row.attempt, kind: row.kind, from_engine: row.engine, previous_reason: row.reason, elapsed_s: Math.round(ageMs(order.started_at) / 1000), charged: false, ...metadata } }).catch(() => null)
}
/** KINEO-ADS-FIEL-1510 — a foto real que a vaga mostra se virar foto parada (null = não há). */
function stillSourceOf(order: AdsV2OrderRow, row: AdsV2ShotRow): string | null {
  const planned = order.plan?.shots?.find((s) => s.idx === row.idx)
  return adsV2StillSource({ imageUrl: row.image_url, lockUrl: adsV2LockOf(order, row)?.url ?? null, referenceUrls: planned?.referenceUrls ?? null, presenterHolds: planned?.presenterHolds })
}
/** KINEO-ADS-FIEL-1510 — quantos planos do pedido já viraram foto parada. */
function stillsUsedOf(rows: readonly AdsV2ShotRow[]): number {
  return latestShots(rows).filter((r) => typeof r.reason === 'string' && r.reason.startsWith(ADS_V2_STILL_REASON)).length
}
/**
 * KINEO-ADS-FIEL-1510 — a vaga vira a FOTO parada com o zoom do montador (o caminho do plano `text`: sem motor, sem fal, sem
 * custo, sem cobrança): nova tentativa 'skipped_text' com a foto como stored_url. Só um vence (upsert sem duplicar).
 */
async function stillFallback(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow, url: string, why: string): Promise<boolean> {
  const next = {
    order_id: order.id, idx: row.idx, attempt: row.attempt + 1, role: row.role, kind: 'text', source: row.source, source_footage_id: row.source_footage_id,
    image_url: url, engine: null, prompt: null, gen_seconds: null, cut_start: 0, cut_seconds: row.cut_seconds, movement_variant: row.movement_variant,
    status: 'skipped_text', stored_url: url, reason: `${ADS_V2_STILL_REASON}:${why}`.slice(0, 200),
  }
  const ins = await admin.from('ads_v2_shots').upsert(next, { onConflict: 'order_id,idx,attempt', ignoreDuplicates: true }).select('id')
  const won = !ins.error && Array.isArray(ins.data) && ins.data.length > 0
  if (won) await shotFallbackEvent(order, row, { to: 'still', reason: why.slice(0, 160), next_attempt: next.attempt })
  return won
}
/** KINEO-ADS-FIEL-1510 — o prompt de movimento do vídeo: quadro travado = o produto parado; foto real do produto = movimento de produto. */
function videoPromptOf(order: AdsV2OrderRow, row: AdsV2ShotRow): string {
  if (row.engine === 'kling_avatar' || row.engine === 'pixverse_effect') return row.prompt ?? ''
  const inHand = inHandTagOf(order, row.idx); if (inHand && row.image_url === inHand.fallbackUrl) return motionPrompt('product', row.movement_variant) // KINEO-ADS-PRODUTO-NA-MAO-1610 — o plano novo que caiu na foto real anima como produto
  const lock = adsV2LockOf(order, row)
  if (!lock) return row.prompt ?? ''
  if (adsV2IsLockedImage(row.image_url)) return adsV2ProductLockMotion(lock.mode, row.movement_variant)
  if (row.image_url === lock.url) return motionPrompt('product', row.movement_variant)
  return row.prompt ?? ''
}
/**
 * KINEO-ADS-FIEL-1510 — a cena PNG do Nano Banana com o recorte REAL colado. 'skip' = sem trava (desligada para esta conta, ou o
 * servidor não carregou): o caminho de antes. 'done' = o plano já foi marcado (quadro travado, ou — falhou — a foto real do produto;
 * no ator, que precisa do rosto, a falha volta ao caminho de antes).
 */
async function finishLockedImage(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow, lock: AdsV2ProductLock, sceneUrl: string): Promise<'skip' | 'done'> {
  const srv = await lockServer()
  if (!srv || !(await srv.adsV2ProductLockEnabled(order.user_id).catch(() => false))) return 'skip'
  // KINEO-ADS-FIEL-2-1510 — CONFERÊNCIA: a cena de gente nasce sem produto; se ainda veio um desenhado, refaz UMA vez (nova imagem, mesmo
  // KINEO-ADS-FIEL-2-1510 — pedido) e, de novo, a vaga anima a FOTO REAL do produto. Conferência que falha (null) = a cena segue.
  const dup = lock.mode === 'scene' ? adsV2LockDupStep({ found: await lockVision().then((v) => (v ? v.adsV2SceneHasProduct(sceneUrl) : null)).catch(() => null), previousReason: row.reason }) : 'keep' // KINEO-ADS-FIEL-2-1510
  if (dup === 'retry') { // KINEO-ADS-FIEL-2-1510
    if (await markShot(admin, row, ['image_submitted'], { status: 'pending', image_request_id: null, image_submit_claimed_at: null, reason: ADS_V2_LOCK_DUP_REASON })) await shotFallbackEvent(order, row, { to: 'scene_retry', reason: ADS_V2_LOCK_DUP_REASON }) // KINEO-ADS-FIEL-2-1510
    return 'done' // KINEO-ADS-FIEL-2-1510
  } // KINEO-ADS-FIEL-2-1510
  if (dup === 'product_photo') { // KINEO-ADS-FIEL-2-1510
    if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: lock.url, reason: null })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: 'lock_duplicate' }) // KINEO-ADS-FIEL-2-1510
    return 'done' // KINEO-ADS-FIEL-2-1510
  } // KINEO-ADS-FIEL-2-1510
  try {
    if (lock.mode === 'scene' && typeof srv.adsV2FinishReservedScene === 'function') return await finishReservedScene(admin, order, row, lock, sceneUrl, srv) // KINEO-ADS-FIEL-4-1510 — o produto vai ao CANTO reservado (servidor antigo sem a função = o caminho da Fiel 3)
    const layout = lock.mode === 'scene' ? await lockVision().then((v) => (v && typeof v.adsV2SceneLayout === 'function' ? v.adsV2SceneLayout(sceneUrl) : null)).catch(() => null) : null // KINEO-ADS-FIEL-3-1510 — a superfície vazia e os rostos (null = a regra fixa: terço de baixo, num dos lados)
    const out = await srv.adsV2FinishLockedScene({ userId: order.user_id, orderId: order.id, idx: row.idx, attempt: row.attempt, lock, format: adsV2PlanFormat(order.plan), sceneUrl, ...(lock.mode === 'scene' ? { layout } : {}) }) // KINEO-ADS-FIEL-3-1510
    if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: out.url })) {
      await writeServerEvent({ name: 'ads_v2_product_locked', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, idx: row.idx, attempt: row.attempt, mode: lock.mode, rect: out.rect, ...((out as { shade?: unknown }).shade ? { shade: (out as { shade?: unknown }).shade } : {}), ...((out as { placement?: unknown }).placement ? { placement: (out as { placement?: unknown }).placement, faces: layout ? layout.faces.length : null, from_original: !!lock.sourceUrl } : {}) } }).catch(() => null) // KINEO-ADS-FIEL-2-1510 — + o tom e a sombra · KINEO-ADS-FIEL-3-1510 — + onde pousou (superfície/rostos/regra fixa), quantos rostos e se o recorte veio da foto original
    }
    return 'done'
  } catch (e) {
    const why = e instanceof Error ? e.message : String(e)
    if (lock.mode === 'actor') { await shotFallbackEvent(order, row, { to: 'unlocked', reason: `lock_finish:${why}`.slice(0, 160) }); return 'skip' }
    if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: lock.url })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: `lock_finish:${why}`.slice(0, 160) })
    return 'done'
  }
}
