  const ihLib = inHand ? await inHandLib() : null // KINEO-ADS-PRODUTO-NA-MAO-1610
  if (inHand && (!ihLib || !(await inHandEnabled(order.user_id)))) { if (await markShot(admin, row, ['pending'], { status: 'image_done', image_url: inHand.fallbackUrl })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: ihLib ? 'in_hand_off' : 'in_hand_lib' }); return } // KINEO-ADS-PRODUTO-NA-MAO-1610 — desligado para a conta = a foto real do produto
  // KINEO-ADS-FIEL-1510 — TRAVA DO PRODUTO: o ESBOÇO (recorte real no lugar, sobre cinza) vira a 1ª referência e a cena volta em PNG
  // KINEO-ADS-FIEL-1510 — para o recorte ser colado de novo sem perda. Falhou o recorte/esboço = o plano anima a FOTO REAL do produto
  // KINEO-ADS-FIEL-1510 — (no ator, que precisa do rosto, o caminho de antes). Sem trava (ou desligada para a conta) = nada muda.
