/**
 * KINEO-ADS-FIEL-4-1510 — a cena de gente com a trava: o recorte REAL vai ao CANTO reservado (lado pela ordem da cena; base no terço de baixo).
 * A conferência ('high') só decide se o canto está ocupado: confiável e com gente no canto = refaz a imagem UMA vez (scene_retry, a mesma régua
 * da Fiel 2) e, de novo, a vaga anima a FOTO REAL do produto. Conferência suspeita ou fora do ar = o canto fica. Falha do servidor = a foto real.
 */
async function finishReservedScene(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow, lock: AdsV2ProductLock, sceneUrl: string, srv: NonNullable<Awaited<ReturnType<typeof lockServer>>>): Promise<'done'> { // KINEO-ADS-FIEL-4-1510
  const side = lockSideOf(order, row) // KINEO-ADS-FIEL-4-1510
  const format = adsV2PlanFormat(order.plan) // KINEO-ADS-FIEL-4-1510
  try { // KINEO-ADS-FIEL-4-1510
    const check = await lockVision().then((v) => (v && typeof v.adsV2SceneCheck === 'function' ? v.adsV2SceneCheck(sceneUrl, format, side) : null)).catch(() => null) // KINEO-ADS-FIEL-4-1510
    const previous = await lockSeenOfSiblings(admin, order, row) // KINEO-ADS-FIEL-4-1510
    const history = typeof srv.adsV2ReadLockChecks === 'function' ? await srv.adsV2ReadLockChecks({ userId: order.user_id, orderId: order.id, rows: await lockSiblingRows(admin, order, row) }) : [] // KINEO-ADS-FIEL-6-1610 — o que a conferência disse nas OUTRAS cenas travadas (repetição e limite global)
    const out = await srv.adsV2FinishReservedScene({ userId: order.user_id, orderId: order.id, idx: row.idx, attempt: row.attempt, lock, format, sceneUrl, side, check, previous, history, totalScenes: lockSceneCount(order), tryN: adsV2LockCheckTry(row.reason) }) // KINEO-ADS-FIEL-4-1510 · KINEO-ADS-FIEL-6-1610 — + o histórico, o total de cenas travadas e a tentativa (1ª ou depois da refação)
    const checkInfo = { trusted: out.trust.trusted, why: out.trust.why, corner_person: check ? check.cornerPerson : null, corner_surface: check ? check.cornerSurface : null, round: !!check && Array.isArray(check.faces) && check.faces.some(adsV2LockBoxRound), top_edge_raw: check && typeof check.topEdgeY === 'number' ? check.topEdgeY : null, corner: out.corner ?? null, people: check && Array.isArray(check.people) ? check.people.length : null, guess: typeof out.guess === 'number' ? out.guess : null } // KINEO-ADS-FIEL-5-1510 — + check.round (caixa na grade de 0,05) e a borda do tampo crua · KINEO-ADS-FIEL-6-1610 — + por que o canto ficou/saiu e quantos corpos · KINEO-ADS-FIEL-7-1610 — + quantas caixas eram chute
    if (out.busy) { // KINEO-ADS-FIEL-4-1510
      if (adsV2LockCornerStep({ busy: true, previousReason: row.reason }) === 'retry') { // KINEO-ADS-FIEL-4-1510
        if (await markShot(admin, row, ['image_submitted'], { status: 'pending', image_request_id: null, image_submit_claimed_at: null, reason: ADS_V2_LOCK_CORNER_REASON })) await shotFallbackEvent(order, row, { to: 'scene_retry', reason: ADS_V2_LOCK_CORNER_REASON, side, problem: out.problem, check: checkInfo }) // KINEO-ADS-FIEL-4-1510
        return 'done' // KINEO-ADS-FIEL-4-1510
      } // KINEO-ADS-FIEL-4-1510
      if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: lock.url, reason: null })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: 'lock_corner_busy', side, problem: out.problem, check: checkInfo }) // KINEO-ADS-FIEL-4-1510
      return 'done' // KINEO-ADS-FIEL-4-1510
    } // KINEO-ADS-FIEL-4-1510
    if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: out.url })) { // KINEO-ADS-FIEL-4-1510
      await writeServerEvent({ name: 'ads_v2_product_locked', userId: order.user_id, path: '/lib/ads/v2Advance', metadata: { order_id: order.id, idx: row.idx, attempt: row.attempt, mode: lock.mode, rect: out.rect, shade: out.shade, placement: out.placement, faces: out.faces, check: checkInfo, from_original: !!lock.sourceUrl } }).catch(() => null) // KINEO-ADS-FIEL-4-1510 — placement.source 'reserved' + o que a conferência disse
    } // KINEO-ADS-FIEL-4-1510
    return 'done' // KINEO-ADS-FIEL-4-1510
  } catch (e) { // KINEO-ADS-FIEL-4-1510
    const why = e instanceof Error ? e.message : String(e) // KINEO-ADS-FIEL-4-1510
    if (await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: lock.url })) await shotFallbackEvent(order, row, { to: 'product_photo', reason: `lock_finish:${why}`.slice(0, 160) }) // KINEO-ADS-FIEL-4-1510
    return 'done' // KINEO-ADS-FIEL-4-1510
  } // KINEO-ADS-FIEL-4-1510
} // KINEO-ADS-FIEL-4-1510

// ── acompanhamento de um plano ────────────────────────────────────────────────────────────────────────────────────
async function pollOne(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow): Promise<void> {
  const ctx = { userId: order.user_id, orderId: order.id }
  switch (row.status) {
    case 'pending':
    case 'image_done': {
      // Carimbo de envio sem desfecho (a lambda morreu entre o carimbo e o POST): ambíguo vencido depois de 20 min.
      const claim = row.status === 'pending' && row.source === 'generated_scene' && !row.image_url ? row.image_submit_claimed_at : row.submit_claimed_at
      if (claim && ageMs(claim) > ADS_V2_AMBIGUOUS_MAX_MS) await failShot(admin, row, [row.status], 'claim_without_outcome', 'transport_timeout_5xx')
      return
    }
    case 'ambiguous': {
      if (ageMs(row.updated_at) > ADS_V2_AMBIGUOUS_MAX_MS) await failShot(admin, row, ['ambiguous'], `${row.reason ?? 'ambiguous'}_expired`, 'transport_timeout_5xx')
      return
    }
    case 'image_submitted': {
      if (!row.image_request_id) return
      const p = await pollSceneImage(row.image_request_id, ctx)
      if (p.state === 'done' && p.url) {
        if (inHandTagOf(order, row.idx)) { await finishInHandImage(admin, order, row, p.url); return } // KINEO-ADS-PRODUTO-NA-MAO-1610 — o juiz do rótulo antes de virar vídeo
        const pv = row.kind === ADS_V2_PRESENTER_KIND ? await presenterV2Of(order) : null // KINEO-APRESENTADOR-V2-1710
        if (pv) { await finishPresenterV2Image(admin, order, row, p.urls && p.urls.length > 0 ? p.urls : [p.url], pv); return } // KINEO-APRESENTADOR-V2-1710 — as 4 opções: cópia, "frasco e caixa", a melhor
        const lock = adsV2LockOf(order, row) // KINEO-ADS-FIEL-1510 — cena de produto: o recorte REAL colado antes de virar vídeo
        if (lock && (await finishLockedImage(admin, order, row, lock, p.url)) === 'done') return // KINEO-ADS-FIEL-1510
        const stored = await persistSceneImage({ userId: order.user_id, orderId: order.id, idx: row.idx, attempt: row.attempt, falUrl: p.url })
        if (stored) await markShot(admin, row, ['image_submitted'], { status: 'image_done', image_url: stored })
        else if (ageMs(row.updated_at) > ADS_V2_COPY_MAX_MS) await failShot(admin, row, ['image_submitted'], 'image_copy_failed', 'unknown')
      } else if (p.state === 'failed') {
        await failShot(admin, row, ['image_submitted'], 'image_provider_failed', 'unknown')
      } else if (ageMs(row.image_submit_claimed_at ?? row.updated_at) > (row.kind === ADS_V2_PRESENTER_KIND ? Math.max(ADS_V2_SHOT_STUCK_MS, cenaUgcAttemptDeadline(row)) : ADS_V2_FAST_IMAGE_STUCK_MS)) { // KINEO-ADS-FIEL-1510 — prazo curto da imagem (o ator mantém o de antes) // KINEO-ADS-CENA-2110
        if (await markShot(admin, row, ['image_submitted'], { status: 'stuck', reason: 'image_stuck', reason_class: 'unknown' })) cancelAbandoned(row, 'image') // KINEO-ADS-FIEL-1510 — na fila, a fal não cobra
      }
      return
    }
    case 'submitted': {
      let falUrl = row.fal_url
      if (!falUrl) {
        if (!row.request_id || !row.engine) return
        const p = await pollFalJob(ADS_V2_ENGINES[row.engine].slug, row.request_id, 'video', ctx)
        if (p.state === 'failed') { await failShot(admin, row, ['submitted'], 'provider_failed', 'unknown'); return }
        if (p.state !== 'done' || !p.url) {
          const ihLate = inHandTagOf(order, row.idx) // KINEO-ADS-MAO-AJUSTE-1610 — o plano "produto na mão" tem prazo próprio no Kling
          const late = ageMs(row.submitted_at ?? row.updated_at) > (row.kind === ADS_V2_PRESENTER_KIND ? Math.max(ADS_V2_SHOT_STUCK_MS, cenaUgcAttemptDeadline(row)) : ihLate && row.engine === 'kling_o3' ? ADS_V2_IN_HAND_VIDEO_STUCK_MS : ADS_V2_FAST_VIDEO_STUCK_MS) // KINEO-ADS-FIEL-1510 — prazo curto por tentativa (o ator mantém o de antes) · KINEO-ADS-MAO-AJUSTE-1610 — Kling do produto na mão: 5 min // KINEO-ADS-CENA-2110
          const again = late && ihLate ? await pollFalJob(ADS_V2_ENGINES[row.engine].slug, row.request_id, 'video', ctx) : null // KINEO-ADS-MAO-AJUSTE-1610 — ANTES do "travado", a fal de novo: COMPLETED = usa o clipe (no T1 pagamos 5 e usamos 1)
          if (again?.state === 'failed') { await failShot(admin, row, ['submitted'], 'provider_failed', 'unknown'); return } // KINEO-ADS-MAO-AJUSTE-1610
          if (again?.state !== 'done' || !again.url) { // KINEO-ADS-MAO-AJUSTE-1610 — nem pronto na 2ª consulta: o travado de sempre
            if (late && (await markShot(admin, row, ['submitted'], { status: 'stuck', reason: 'shot_stuck', reason_class: 'unknown' }))) cancelAbandoned(row, 'video') // KINEO-ADS-FIEL-1510 — job na fila é cancelado
            return
          } // KINEO-ADS-MAO-AJUSTE-1610
          falUrl = again.url // KINEO-ADS-MAO-AJUSTE-1610 — o clipe que ficou pronto no limite do prazo
        } else falUrl = p.url // KINEO-ADS-MAO-AJUSTE-1610 — era `falUrl = p.url` depois do if
        await markShot(admin, row, ['submitted'], { fal_url: falUrl, fal_done_at: nowIso() })
      }
      // A URL da fal expira: o plano só fica 'done' com a cópia no NOSSO bucket e a duração medida no mvhd.
      const copy = await persistShotClip({ userId: order.user_id, orderId: order.id, idx: row.idx, attempt: row.attempt, falUrl })
      if (copy) {
        const need = (num(row.cut_start) ?? 0) + (num(row.cut_seconds) ?? 0) + 0.25
        if (copy.measuredSeconds + 1e-6 < need) {
          await failShot(admin, row, ['submitted'], `clip_too_short:${copy.measuredSeconds}<${need}`, 'unknown')
          return
        }
        await markShot(admin, row, ['submitted'], { status: 'done', stored_url: copy.storedUrl, measured_seconds: copy.measuredSeconds, reason: null })
      } else if (ageMs(row.fal_done_at ?? nowIso()) > ADS_V2_COPY_MAX_MS) {
        await failShot(admin, row, ['submitted'], 'clip_copy_failed', 'unknown')
      }
      return
    }
    default:
      return
  }
}

/**
 * Plano que falhou por culpa do fornecedor ganha nova tentativa SEM cobrar (2ª no principal, 3ª no H3). Devolve o
 * motivo terminal quando não há mais tentativa (o pedido inteiro falha e estorna).
 */
async function retryOrTerminal(admin: SupabaseClient, order: AdsV2OrderRow, row: AdsV2ShotRow, stills: { used: number } = { used: 0 }): Promise<string | null> { // KINEO-ADS-FIEL-1510 — stills: fotos paradas já usadas no pedido
  // KINEO-ADS-CENA-2110 — UGC exige a pessoa: uma refação, depois falha terminal com estorno.
  if (row.kind === ADS_V2_PRESENTER_KIND) return retryPresenter(admin, order, row)
  if (row.kind === 'text') return `text_shot_${row.idx}_${row.status}` // nunca acontece: text nasce skipped_text
  if (row.kind === 'user_video') return `user_video_shot_${row.idx}_${row.status}` // nunca acontece: nasce 'done', sem IA
  // KINEO-ESTILOS-PRODUTO-2026-10-09 — o efeito da PixVerse sem acesso (404/403 de modelo = 'auth_model_access') NÃO mata o
  // anúncio: o plano segue para a próxima tentativa e cai na reserva H3, que é outro modelo. Saldo da fal (balance_quota)
  // continua terminal (a conta é a mesma para todos os motores).
  const effectAccess = row.engine === 'pixverse_effect' && row.reason_class === 'auth_model_access'
  if (row.reason_class && ADS_V2_NON_RETRY_CLASSES.includes(row.reason_class) && !effectAccess) return `shot_${row.idx}_${row.reason_class}`
  // Efeito sem acesso: pula direto para a reserva (repetir o mesmo modelo fechado só queima tempo).
  const nextAttempt = effectAccess ? Math.max(row.attempt + 1, ADS_V2_FALLBACK_FROM_ATTEMPT) : row.attempt + 1 // KINEO-ADS-FIEL-1510 — era `attempt`
  // KINEO-ADS-FIEL-1510 — PRAZO: a régua de antes enquanto couber em ~6,5 min desde o início; não cabendo, pula para a reserva H3;
  // KINEO-ADS-FIEL-1510 — nem ela cabendo (ou esgotada), a FOTO parada (até 2 por pedido). Sem foto parada: a régua de antes, e
  // KINEO-ADS-FIEL-1510 — esgotada = terminal com estorno, a MESMA frase de antes. Nada disto cobra o cliente.
  const styled = adsV2ShotEffect(order.plan, row.idx) !== null // KINEO-ADS-FIEL-1510
  const shotKind = row.kind // KINEO-ADS-FIEL-1510 — o tipo já sem o ator (o callback abaixo perde o estreitamento)
  const stillUrl = stillSourceOf(order, row) // KINEO-ADS-FIEL-1510
  const inHandVideo = !!inHandTagOf(order, row.idx) && row.engine === 'kling_o3' && !!row.image_url // KINEO-ADS-MAO-AJUSTE-1610 — o Kling do produto na mão falhou ou travou (a foto já existe)
  const fallbackIn = { nextAttempt, maxAttempts: ADS_V2_MAX_AUTO_ATTEMPTS, fallbackFrom: ADS_V2_FALLBACK_FROM_ATTEMPT, elapsedMs: ageMs(order.started_at), needsImage: row.source === 'generated_scene' && !row.image_url, stillsUsed: stills.used, canStill: !!stillUrl, skipPrincipal: (row.status === 'stuck' && row.reason === 'shot_stuck') || inHandVideo, route: (a: number) => routeShot(shotKind, order.tier, a, styled) } // KINEO-ADS-FIEL-1510 — vídeo preso no principal = direto à reserva · KINEO-ADS-MAO-AJUSTE-1610 — produto na mão: Kling falhou = plano B no H3 (sem 2º Kling)
  const step = inHandVideo ? adsV2FallbackStepTimed({ ...fallbackIn, typical: ADS_V2_IN_HAND_ENGINE_TYPICAL_MS, stillAtMs: ADS_V2_IN_HAND_STILL_AT_MS }) : adsV2FallbackStep(fallbackIn) // KINEO-ADS-MAO-AJUSTE-1610 — o prazo do produto na mão; os outros modos, a régua de sempre
  if (step.step === 'terminal') return `shot_${row.idx}_exhausted:${row.reason ?? row.status}` // KINEO-ADS-FIEL-1510 — a frase de antes
  if (step.step === 'still') { if (stillUrl && (await stillFallback(admin, order, row, stillUrl, `${row.status}:${row.reason ?? ''}`))) stills.used += 1; return null } // KINEO-ADS-FIEL-1510
  const attempt = step.attempt // KINEO-ADS-FIEL-1510
  const engine = routeShot(row.kind, order.tier, attempt, styled) // KINEO-ADS-FIEL-1510 — o mesmo routeShot de antes
  if (!engine) return `shot_${row.idx}_no_engine`
  // Cena criada cuja IMAGEM já saiu reaproveita a imagem (só o vídeo falhou); falha na imagem recomeça pela imagem.
  const keepImage = row.source === 'client_photo' || !!row.image_url
  const next = {
    order_id: order.id,
    idx: row.idx,
    attempt,
    role: row.role,
    kind: row.kind,
    source: row.source,
    source_footage_id: row.source_footage_id,
    image_url: keepImage ? row.image_url : null,
    engine,
    prompt: row.prompt,
    gen_seconds: ADS_V2_ENGINES[engine].genSeconds,
    cut_start: inHandVideo && engine === 'h3' ? ((await inHandLib())?.adsV2InHandH3CutStart(num(row.cut_seconds) ?? 0) ?? 0) : row.cut_start, // KINEO-ADS-MAO-AJUSTE-1610 — plano B no H3: só o começo, corte ≤ 2,5 s (depois o produto cresce)
    cut_seconds: row.cut_seconds,
    movement_variant: row.movement_variant,
    status: row.source === 'generated_scene' && keepImage ? 'image_done' : 'pending',
  }
  const ins = await admin.from('ads_v2_shots').upsert(next, { onConflict: 'order_id,idx,attempt', ignoreDuplicates: true }).select('id')
  if (!ins.error && Array.isArray(ins.data) && ins.data.length > 0) {
    await writeServerEvent({
      name: 'ads_v2_shot_retried',
      userId: order.user_id,
      path: '/lib/ads/v2Advance',
      metadata: { order_id: order.id, idx: row.idx, attempt, engine, previous_reason: row.reason, previous_class: row.reason_class, charged: false },
    })
